import { AnyClass, Awaitable, Empty } from '../types';
import {
  AppContext,
  AppServiceClass,
  AppProvideArgs,
  AppProvidedMerged,
  AppProvideOptions,
  AppContextUsed,
  AppContextState,
} from './types';

const ProvidePrefix = 'provide:';

const getMethodDescriptor = (cls: AnyClass, key: PropertyKey) => {
  let proto = cls.prototype;
  while (proto && proto !== Object.prototype) {
    const desc = Object.getOwnPropertyDescriptor(proto, key as any);
    if (desc) return desc;
    proto = Object.getPrototypeOf(proto);
  }
  return undefined;
};

type ProvideRecord = {
  classRef: AnyClass;
  factory: (ctx: AppContextCore<any, any>) => any;
};

type LoadEntry = {
  classRef: AnyClass;
  inst: any;
};

type ObjectStep = (ctx: AppContextCore<any, any>) => void;

const isPromiseLike = (value: any): value is Promise<any> =>
  !!value && typeof value.then === 'function';

export class AppContextCore<Cur = Empty, Req = Empty> {
  private __current: Cur;
  private __required: Req;

  private provideRecords: ProvideRecord[] = [];
  private registry = new Map<string | AnyClass, LoadEntry>();
  private objectSteps: ObjectStep[] = [];
  started = false;
  private starting = false;
  private settleCursor = 0;
  private recordEntries = new Map<ProvideRecord, LoadEntry>();
  private pendingInitQueue: LoadEntry[] = [];
  private pendingInitSet = new Set<LoadEntry>();
  private initializedEntries = new Set<LoadEntry>();
  private loadingRecords = new Set<ProvideRecord>();
  private settlementChain: Promise<void> = Promise.resolve();
  private settlementError: unknown = null;
  private settling = false;

  private assertSettlementHealthy() {
    if (this.settlementError) {
      throw this.settlementError;
    }
  }

  private enqueueInit(entry: LoadEntry) {
    if (this.initializedEntries.has(entry) || this.pendingInitSet.has(entry)) {
      return;
    }
    this.pendingInitSet.add(entry);
    this.pendingInitQueue.push(entry);
  }

  private sortInitQueueByDeclarationOrder() {
    if (this.pendingInitQueue.length <= 1) return;
    const order = new Map<LoadEntry, number>();
    let idx = 0;
    for (const record of this.provideRecords) {
      const entry = this.recordEntries.get(record);
      if (entry) order.set(entry, idx++);
    }
    this.pendingInitQueue.sort(
      (a, b) => (order.get(a) ?? Infinity) - (order.get(b) ?? Infinity),
    );
  }

  private async constructPendingRecords() {
    while (this.settleCursor < this.provideRecords.length) {
      const record = this.provideRecords[this.settleCursor];
      this.settleCursor += 1;
      await this.createEntryFromRecord(record);
    }
    // Re-sort the init queue to match declaration order.
    // On-demand creation triggered by get() inside a factory constructor
    // can enqueue a dependency before the service that requested it,
    // which would invert the intended init order.
    this.sortInitQueueByDeclarationOrder();
  }

  private async settlePending() {
    await this.constructPendingRecords();

    while (this.pendingInitQueue.length > 0) {
      const entry = this.pendingInitQueue.shift()!;
      this.pendingInitSet.delete(entry);
      if (this.initializedEntries.has(entry)) {
        continue;
      }

      const inst = await entry.inst;
      entry.inst = inst;
      if (inst && typeof inst.init === 'function') {
        await inst.init();
      }
      this.initializedEntries.add(entry);

      // Providers added during this init must settle and init immediately
      // after current init, before previous remaining init queue items.
      const remaining = this.pendingInitQueue.splice(0);
      await this.constructPendingRecords();
      this.pendingInitQueue.push(...remaining);
    }
  }

  private scheduleSettlement() {
    const run = async () => {
      this.assertSettlementHealthy();
      this.settling = true;
      try {
        await this.settlePending();
      } catch (error) {
        this.settlementError = error;
        throw error;
      } finally {
        this.settling = false;
      }
    };

    const task = this.settlementChain.then(run, run);
    this.settlementChain = task.catch(() => undefined);
    return task;
  }

  private triggerSettlement() {
    void this.scheduleSettlement();
  }

  private findProvideRecord(key: AnyClass): ProvideRecord | undefined {
    for (let i = 0; i < this.provideRecords.length; i += 1) {
      const record = this.provideRecords[i];
      if (record.classRef === key && !this.recordEntries.has(record)) {
        return record;
      }
    }
    return undefined;
  }

  private createEntryFromRecord(record: ProvideRecord): Awaitable<LoadEntry> {
    const existing = this.recordEntries.get(record);
    if (existing) {
      return existing;
    }

    if (this.loadingRecords.has(record)) {
      throw new Error(
        `Circular dependency detected while providing: ${record.classRef?.name ?? 'UnknownService'}`,
      );
    }

    this.loadingRecords.add(record);
    try {
      const entry: LoadEntry = {
        classRef: record.classRef,
        inst: record.factory(this),
      };
      this.recordEntries.set(record, entry);
      this.registry.set(record.classRef, entry);
      this.enqueueInit(entry);
      if (isPromiseLike(entry.inst)) {
        return entry.inst.then((resolvedInst: any) => {
          entry.inst = resolvedInst;
          return entry;
        });
      }
      return entry;
    } finally {
      this.loadingRecords.delete(record);
    }
  }

  provide<
    C extends AppServiceClass<Cur, Req>,
    const P extends string = '',
    const M extends (keyof InstanceType<C>)[] = [],
  >(
    cls: C,
    ...args: AppProvideArgs<Cur, Req, C, P, M>
  ): AppProvidedMerged<Cur, Req, C, P, M> {
    this.assertSettlementHealthy();

    const last = args[args.length - 1] as any;
    const hasOptions =
      !!last &&
      typeof last === 'object' &&
      ('provide' in last ||
        'merge' in last ||
        'useValue' in last ||
        'useFactory' in last ||
        'useClass' in last);

    const options = (hasOptions ? last : undefined) as
      | AppProvideOptions<Cur, Req, C, P, M>
      | undefined;

    const _args = (
      hasOptions ? args.slice(0, -1) : args
    ) as ConstructorParameters<C>;

    const classRef = cls as unknown as AnyClass;

    // Create factory function that will be called during start() with the target ctx.
    const factory = (ctx: AppContextCore<any, any>) =>
      options?.useValue ??
      (options?.useFactory
        ? options.useFactory(ctx as any, ..._args)
        : new (options?.useClass ?? cls)(ctx as any, ..._args));

    // Record the provide configuration
    this.provideRecords.push({
      classRef,
      factory,
    });

    // Set up property accessors if needed
    if (options?.provide) {
      const prop = options.provide;
      const step: ObjectStep = (ctx) => {
        Object.defineProperty(ctx, prop, {
          enumerable: true,
          configurable: true,
          get: () => {
            const currentEntry = ctx.registry.get(classRef);
            return currentEntry?.inst;
          },
        });
      };
      step(this);
      this.objectSteps.push(step);
    }

    if (options?.merge?.length) {
      for (const key of options.merge) {
        const desc = getMethodDescriptor(cls, key);
        const isMethod = !!desc && typeof desc.value === 'function';

        const step: ObjectStep = (ctx) => {
          if (isMethod) {
            Object.defineProperty(ctx, key, {
              enumerable: true,
              configurable: true,
              get: () => {
                const currentEntry = ctx.registry.get(classRef);
                const currentInst = currentEntry?.inst;
                const fn = (currentInst as any)?.[key];
                return typeof fn === 'function' ? fn.bind(currentInst) : fn;
              },
            });
            return;
          }

          Object.defineProperty(ctx, key, {
            enumerable: true,
            configurable: true,
            get: () => {
              const currentEntry = ctx.registry.get(classRef);
              return (currentEntry?.inst as any)?.[key];
            },
            set: (value: any) => {
              const currentEntry = ctx.registry.get(classRef);
              if (!currentEntry) return;
              (currentEntry.inst as any)[key] = value;
            },
          });
        };
        step(this);
        this.objectSteps.push(step);
      }
    }

    return this as any;
  }

  get<R>(
    cls:
      | AppServiceClass<Cur, Req, any, R>
      | (() => AppServiceClass<Cur, Req, any, R>),
  ): R {
    this.assertSettlementHealthy();

    let key = cls as unknown as AnyClass;
    if (
      !this.registry.has(key) &&
      typeof cls === 'function' &&
      !(cls as any).prototype
    ) {
      key = (cls as () => AppServiceClass<Cur, Req, any, R>)() as AnyClass;
    }

    if (!this.registry.has(key) && (this.starting || this.settling)) {
      const record = this.findProvideRecord(key);
      if (record) {
        this.createEntryFromRecord(record);
      }
    }

    if (!this.registry.has(key)) {
      throw new Error(`Service not provided: ${key?.name ?? cls.name}`);
    }

    const entry = this.registry.get(key)!;
    return entry.inst as any;
  }

  async getAsync<R>(
    cls:
      | AppServiceClass<Cur, Req, any, R>
      | (() => AppServiceClass<Cur, Req, any, R>),
  ): Promise<R> {
    return await this.get(cls);
  }

  use<const Ctxes extends AppContext<any, any>[]>(
    ...ctxes: Ctxes
  ): AppContextUsed<Cur, Req, Ctxes> {
    this.assertSettlementHealthy();

    for (const ctx of ctxes) {
      const other = ctx as any as AppContextCore<any, any>;

      // Started contexts are merged by instance directly (registry copy),
      // and should not queue reconstruction/re-init on target context.
      if (Array.isArray(other?.provideRecords) && !other?.started) {
        this.provideRecords.push(...other.provideRecords);
      }

      // Copy and apply object steps
      if (Array.isArray(other?.objectSteps)) {
        this.objectSteps.push(...other.objectSteps);
        for (const step of other.objectSteps) {
          step(this);
        }
      }

      // If the other context has already started, copy loaded entries only.
      // They should remain initialized by the source context and must not be re-initialized.
      if (other?.started) {
        if (other?.registry instanceof Map) {
          for (const [key, value] of other.registry.entries()) {
            this.registry.set(key, value);
          }
        }
      }
    }

    return this as any;
  }

  define(): AppContext<Cur, Req> {
    this.assertSettlementHealthy();
    if (this.started && !this.starting) {
      this.triggerSettlement();
    }
    return this as any;
  }

  async start(): Promise<Empty extends Req ? AppContext<Cur, Req> : never> {
    if (this.started) {
      return this as any;
    }

    this.assertSettlementHealthy();
    this.starting = true;
    try {
      await this.scheduleSettlement();
      this.started = true;
      return this as any;
    } finally {
      this.starting = false;
    }
  }
}

export const createAppContext = <Req = Empty>() =>
  new AppContextCore<Empty, Req>() as AppContext<Empty, Req>;
